// Lowest common ancestor in a binary tree (no parent pointers).
TreeNode* lca(TreeNode* node, TreeNode* p, TreeNode* q) {
    if (!node || node == p || node == q) return node;
    TreeNode* left  = lca(node->left, p, q);
    TreeNode* right = lca(node->right, p, q);
    if (left && right) return node;       // split point -> LCA
    return left ? left : right;
}

def lca(node, p, q):
    if not node or node is p or node is q:
        return node
    left = lca(node.left, p, q)
    right = lca(node.right, p, q)
    if left and right:
        return node          # split point → LCA
    return left or right

class Solution {
public:
    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
        if (!root || root == p || root == q) return root;
        TreeNode* L = lowestCommonAncestor(root->left, p, q);
        TreeNode* R = lowestCommonAncestor(root->right, p, q);
        if (L && R) return root;
        return L ? L : R;
    }
};

class Solution:
    def lowestCommonAncestor(self, root, p, q):
        if not root or root == p or root == q:
            return root
        L = self.lowestCommonAncestor(root.left, p, q)
        R = self.lowestCommonAncestor(root.right, p, q)
        if L and R:
            return root
        return L or R

class Solution {
public:
    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
        while (root) {
            if (p->val < root->val && q->val < root->val) root = root->left;
            else if (p->val > root->val && q->val > root->val) root = root->right;
            else return root;
        }
        return nullptr;
    }
};

class Solution:
    def lowestCommonAncestor(self, root, p, q):
        while root:
            if p.val < root.val and q.val < root.val:
                root = root.left
            elif p.val > root.val and q.val > root.val:
                root = root.right
            else:
                return root
        return None

class Solution {
public:
    Node* lowestCommonAncestor(Node* p, Node* q) {
        Node *a = p, *b = q;
        while (a != b) {
            a = a ? a->parent : q;
            b = b ? b->parent : p;
        }
        return a;
    }
};

class Solution:
    def lowestCommonAncestor(self, p, q):
        a, b = p, q
        while a is not b:
            a = a.parent if a else q
            b = b.parent if b else p
        return a

class Solution {
    TreeNode* lca(TreeNode* r, int p, int q) {
        if (!r || r->val == p || r->val == q) return r;
        TreeNode* L = lca(r->left, p, q); TreeNode* R = lca(r->right, p, q);
        if (L && R) return r; return L ? L : R;
    }
    int depth(TreeNode* r, int target, int d) {
        if (!r) return -1;
        if (r->val == target) return d;
        int l = depth(r->left, target, d + 1); if (l != -1) return l;
        return depth(r->right, target, d + 1);
    }
public:
    int distanceBetween(TreeNode* root, int p, int q) {
        TreeNode* a = lca(root, p, q);
        return depth(a, p, 0) + depth(a, q, 0);
    }
};

class Solution:
    def distanceBetween(self, root, p, q):
        def lca(r):
            if not r or r.val in (p, q):
                return r
            L, R = lca(r.left), lca(r.right)
            if L and R:
                return r
            return L or R
        def depth(r, target, d):
            if not r:
                return -1
            if r.val == target:
                return d
            left = depth(r.left, target, d + 1)
            return left if left != -1 else depth(r.right, target, d + 1)
        a = lca(root)
        return depth(a, p, 0) + depth(a, q, 0)

class TreeAncestor {
    vector<vector<int>> up; int LOG;
public:
    TreeAncestor(int n, vector<int>& parent) {
        LOG = 1; while ((1 << LOG) < n) LOG++;
        up.assign(LOG, vector<int>(n, -1));
        for (int v = 0; v < n; v++) up[0][v] = parent[v];
        for (int j = 1; j < LOG; j++)
            for (int v = 0; v < n; v++)
                up[j][v] = up[j-1][v] == -1 ? -1 : up[j-1][up[j-1][v]];
    }
    int getKthAncestor(int node, int k) {
        for (int j = 0; j < LOG && node != -1; j++)
            if (k & (1 << j)) node = up[j][node];
        return node;
    }
};

class TreeAncestor:
    def __init__(self, n: int, parent: list[int]):
        self.LOG = max(1, (n).bit_length())
        self.up = [[-1] * n for _ in range(self.LOG)]
        self.up[0] = parent[:]
        for j in range(1, self.LOG):
            for v in range(n):
                p = self.up[j - 1][v]
                self.up[j][v] = -1 if p == -1 else self.up[j - 1][p]
    def getKthAncestor(self, node: int, k: int) -> int:
        j = 0
        while k and node != -1:
            if k & 1:
                node = self.up[j][node]
            k >>= 1
            j += 1
        return node
